// GERADO por scripts/gerar-manuais.mts — não editar à mão. Fonte: docs/manuais/feriados.md
export const html: string = "<h2 id=\"visão-geral\">Visão geral</h2>\n<p><strong>Onde fica:</strong> RH → Parâmetros, aba <strong>Feriados</strong>.</p>\n<p>Os dias cadastrados aqui são <strong>carga zero</strong> no ponto e na folha:</p>\n<ul>\n<li>Hora trabalhada num feriado paga como extra de domingo/feriado (ou diária, conforme o contrato) e o dia não gera falta.</li>\n<li>O lembrete de &quot;sem ponto ontem&quot; do WhatsApp não é enviado em feriado da empresa do funcionário.</li>\n<li>Espelhos de ponto e holerites <strong>em aberto</strong> se recalculam sozinhos quando um feriado entra, muda ou sai. Folhas já fechadas não mudam.</li>\n</ul>\n<p><strong>Para quem vale cada feriado:</strong></p>\n<div class=\"tabela\"><table>\n<thead>\n<tr>\n<th>Tipo</th>\n<th>&quot;Aplica-se a&quot;</th>\n<th>Exemplo</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Nacional</td>\n<td>Todas as empresas</td>\n<td>Natal, Tiradentes</td>\n</tr>\n<tr>\n<td>Estadual</td>\n<td>Todas as empresas (as duas ficam em SP)</td>\n<td>9 de julho</td>\n</tr>\n<tr>\n<td>Municipal</td>\n<td>Só a empresa daquela cidade</td>\n<td>25/01 (São Paulo) só na Rentech; 19/02 (Osasco) só na Alfa Light</td>\n</tr>\n</tbody></table></div>\n<p>O feriado municipal <strong>precisa</strong> ficar preso à empresa da cidade: a Rentech fica em São Paulo e a Alfa Light em Osasco, e o feriado de uma cidade não pode zerar a carga de quem trabalha na outra.</p>\n<h2 id=\"buscar-os-feriados-do-ano\">Buscar os feriados do ano</h2>\n<p>O jeito mais rápido de montar o ano é o botão <strong>🔎 Buscar feriados do ano</strong>, acima do formulário de adicionar.</p>\n<ol>\n<li>Escolha o <strong>ano</strong>. A partir de novembro, a tela já sugere o ano seguinte.</li>\n<li><strong>Incluir estaduais e municipais</strong> (marcado): além dos nacionais, o nosso agente de IA pesquisa na internet as leis do estado e da cidade de cada empresa. Leva de <strong>1 a 2 minutos</strong>. Desmarcado, vêm só os nacionais, na hora.</li>\n<li>Clique em <strong>Buscar</strong>.</li>\n</ol>\n<p><span class=\"figura\"><img src=\"data:image/png;base64,\" alt=\"A janela da busca: ano e a opção de incluir estaduais e municipais\" loading=\"lazy\" /><span class=\"legenda\">A janela da busca: ano e a opção de incluir estaduais e municipais</span></span></p>\n<p><strong>De onde vêm os dados:</strong></p>\n<ul>\n<li><strong>Nacionais:</strong> BrasilAPI, uma fonte pública e oficial. Ela já calcula os feriados móveis (Carnaval, Sexta-feira Santa, Corpus Christi).</li>\n<li><strong>Estaduais e municipais:</strong> o agente de IA pesquisa nos sites da Prefeitura, da Câmara, da Assembleia Legislativa e no Diário Oficial. Cada feriado volta com a <strong>lei</strong>, o <strong>link da fonte</strong> e a <strong>confiança</strong>: alta (confirmado em fonte oficial), média (fonte secundária confiável) ou baixa (não confirmado).</li>\n<li>A cidade e a UF de cada empresa vêm de Parâmetros → Empresas. Empresa sem cidade fica sem a pesquisa municipal, e um aviso diz qual é.</li>\n</ul>\n<h2 id=\"conferir-e-cadastrar\">Conferir e cadastrar</h2>\n<p>Nada é gravado até você clicar em <strong>Cadastrar</strong>. A prévia mostra:</p>\n<ul>\n<li><strong>Avisos</strong> da pesquisa no topo. Por exemplo: &quot;Osasco ainda não publicou o decreto do ano; as datas vieram dos decretos anteriores&quot;.</li>\n<li><strong>Cada feriado:</strong> data e dia da semana, o tipo (Nacional, Estadual ou Municipal com a cidade), para quem vale (Todas as empresas ou o selo da empresa), a lei, observações e o link <strong>fonte</strong>.</li>\n<li><strong>✓ Já cadastrado:</strong> a data já está na tabela. A linha vem travada e mostra o nome que já existe (ex.: &quot;Confraternização mundial → já cadastrado: ANO NOVO&quot;).</li>\n</ul>\n<p><span class=\"figura\"><img src=\"data:image/png;base64,\" alt=\"Prévia de 2027: nacionais, municipais de São Paulo e Osasco, e o estadual de 9 de julho\" loading=\"lazy\" /><span class=\"legenda\">Prévia de 2027: nacionais, municipais de São Paulo e Osasco, e o estadual de 9 de julho</span></span></p>\n<p><strong>Nascem desmarcados</strong> (marque se quiser cadastrar):</p>\n<ul>\n<li>O que <strong>já está cadastrado</strong>.</li>\n<li>O que cai num <strong>domingo</strong> (Páscoa, por exemplo). Não muda o ponto de quem não trabalha no domingo.</li>\n<li>O <strong>municipal que repete uma data nacional</strong> da lista, com o selo &quot;Mesma data do nacional&quot;. Cadastrar os dois não muda nada, porque o nacional já vale para todas as empresas.</li>\n<li>O que a IA <strong>não conseguiu confirmar</strong> (confiança baixa).</li>\n</ul>\n<p>Confira o link <strong>fonte</strong> dos municipais antes de cadastrar, principalmente os de confiança média. Depois clique em <strong>Cadastrar N feriado(s)</strong>. A lista da aba se atualiza na hora. Os botões <strong>Marcar novos</strong> e <strong>Desmarcar</strong> ajudam a escolher.</p>\n<p><strong>Carnaval e Corpus Christi:</strong> pela lei federal são <strong>ponto facultativo</strong>, e a prévia avisa isso. A empresa decide se é folga. Se for, cadastre; se não for, desmarque. Corpus Christi é feriado municipal por lei em São Paulo e em Osasco.</p>\n<p><strong>Custo:</strong> cada busca com estaduais e municipais custa cerca de <strong>US$ 0,50</strong> (uns R$ 3) de uso da IA. A busca só dos nacionais é gratuita. Basta uma busca por ano. Vale repetir em dezembro, quando as prefeituras publicam os decretos do ano seguinte.</p>\n<h2 id=\"cadastrar-editar-e-excluir-à-mão\">Cadastrar, editar e excluir à mão</h2>\n<ul>\n<li><strong>Adicionar:</strong> data, descrição e <strong>Aplica-se a</strong> (Todas as empresas, ou a empresa da cidade), depois <strong>+ Adicionar</strong>. A empresa escolhida continua selecionada, para cadastrar vários seguidos.</li>\n<li><strong>Editar:</strong> ✏️ na linha do feriado.</li>\n<li><strong>Excluir:</strong> X na linha. O sistema pede confirmação, porque espelhos e holerites em aberto daquele dia voltam a ser dia útil.</li>\n<li><strong>Mesma data repetida:</strong> a tabela não aceita a mesma data duas vezes para o mesmo alvo (todas, ou a mesma empresa).</li>\n<li>Quem só enxerga uma empresa (Parâmetros → Permissões) não cadastra feriado para &quot;todas as empresas&quot;. A busca grava uma linha para cada empresa liberada para essa pessoa.</li>\n</ul>\n<h2 id=\"dúvidas-comuns\">Dúvidas comuns</h2>\n<ul>\n<li><strong>A IA trouxe uma data que eu não conheço.</strong> Abra o link <strong>fonte</strong> e confira a lei. Na dúvida, deixe desmarcado e pergunte à contabilidade.</li>\n<li><strong>A busca de estaduais e municipais deu erro.</strong> Os nacionais continuam na prévia e o aviso diz o motivo (ex.: IA sem crédito ou fora do ar). Tente de novo mais tarde ou cadastre o municipal à mão.</li>\n<li><strong>Cadastrei um feriado errado.</strong> Exclua na lista. Espelhos e holerites em aberto se recalculam. Folha já fechada não muda: fale com o RH para reabrir, se for o caso.</li>\n<li><strong>A empresa mudou de cidade.</strong> Atualize a cidade em Parâmetros → Empresas antes de buscar.</li>\n</ul>\n";
export const sumario: { id: string; texto: string }[] = [{"id":"visão-geral","texto":"Visão geral"},{"id":"buscar-os-feriados-do-ano","texto":"Buscar os feriados do ano"},{"id":"conferir-e-cadastrar","texto":"Conferir e cadastrar"},{"id":"cadastrar-editar-e-excluir-à-mão","texto":"Cadastrar, editar e excluir à mão"},{"id":"dúvidas-comuns","texto":"Dúvidas comuns"}];
